//Salida 1: 11 ordenes de movimiento (msg.player = p1...p11)
//Salida 2: situacion tactica en topic equipo/estado

const LARGO = 105;
const ANCHO = 68;
const DT = 1;
const clamp = (v,a,b) => Math.max(a, Math.min(b,v));
const rand = (a,b) => a + Math.random() * (b-a);
const rnd = n => Number(n.toFixed(2));
const posInicial = {
    p1:[4,34], p2:[26,9], p3:[26,59], p4:[22,26], p5:[22,42],
    p6:[50,20], p7:[50,48], p8:[70,34], p9:[83,34],
    p10:[77,10], p11:[77,58]
};
const roles = {
    p1:'portero',p2:'lateral_derecho',p3:'lateral_izquierdo',
    p4:'central_derecho',p5:'central_izquierdo',
    p6:'centrocampista_derecho',p7:'centrocampista_izquierdo',
    p8:'mediapunta',p9:'delantero_centro',
    p10:'extremo_derecho',p11:'extremo_izquierdo'
};
const IDS = Object.keys(posInicial);
const FASES = {
    ataque_organizado:'Ataque organizado',
    transicion_defensiva:'Transicion defensiva',
    presion_alta:'Presion alta',
    defensa_organizada:'Defensa organizada',
    transicion_ofensiva:'Transicion ofensiva'
};
const nuevaPartida = () => ({
    t:0, fase:'ataque_organizado', restante:31, posesion:'propia',
    dueno:'p6', balon:{x:50,y:20}, pase:null, desdePase:0,
    evento:'Inicio de la simulacion', ultimoEvento:0, resets:0
});

//Si alguna no ha publicado aun, usar su posicion inicial.
const reinicio = msg.topic === 'control/reset';
if (reinicio) {
    context.set('partido', null);
    flow.set('posicionesTacticas', null);
}
let s = context.get('partido') || nuevaPartida();
let posiciones = flow.get('posicionesTacticas') || {};
for (const id of IDS) {
    if (!posiciones[id] || !Number.isFinite(posiciones[id].x) || !Number.isFinite(posiciones[id].y)) {
        posiciones[id] = {x:posInicial[id][0],y:posInicial[id][1],vx:0,vy:0};
    }
}

//Cambiar fase desde un nodo Inject opcional (sin cambiar los programas del jugador).
if (msg.topic === 'control/fase') {
    const fase = String(msg.payload || '');
    if (FASES[fase]) {
        s.fase = fase;
        s.restante = fase==='ataque_organizado'?32: fase==='defensa_organizada'?20: 7;
        s.posesion = ['ataque_organizado','transicion_ofensiva'].includes(fase)?'propia':'rival';
        s.pase = null;
        s.dueno = s.posesion==='propia'?'p6':null;
        if (s.dueno) s.balon = {x:posiciones.p6.x,y:posiciones.p6.y};
        s.evento = 'Cambio manual: '+FASES[fase];
        s.ultimoEvento=s.t;
    }
}

//Maquina de estados tacticos (el equipo cambia de fase de manera conjunta).
if (s.restante <= 0) {
    if (s.fase === 'ataque_organizado') {
        s.fase='transicion_defensiva';s.restante=4;
        s.posesion='rival';s.dueno=null;s.pase=null;
        s.evento='Perdida de posesion';
    } else if (s.fase === 'transicion_defensiva') {
        s.fase='presion_alta';s.restante=9;
        s.evento='Activacion de la presion colectiva';
    } else if (s.fase === 'presion_alta') {
        s.fase='defensa_organizada';s.restante=20;
        s.evento='Repliegue y bloque defensivo';
    } else if (s.fase === 'defensa_organizada') {
        s.fase='transicion_ofensiva';s.restante=6;
        s.posesion='propia';s.pase=null;
        // Recuperacion por el jugador mas cercano entre defensas y mediocentros.
        const candidatos=['p2','p3','p4','p5','p6','p7','p8'];
        candidatos.sort((a,b) => Math.hypot(posiciones[a].x-s.balon.x,posiciones[a].y-s.balon.y)
            - Math.hypot(posiciones[b].x-s.balon.x,posiciones[b].y-s.balon.y));
        s.dueno=candidatos[0];
        s.balon={x:posiciones[s.dueno].x,y:posiciones[s.dueno].y};
        s.desdePase=0;
        s.evento='Recuperacion: '+s.dueno.toUpperCase();
    } else {
        s.fase='ataque_organizado';s.restante=Math.round(rand(28,40));
        s.evento='Ataque organizado tras recuperar';
    }
    s.ultimoEvento=s.t;
}

//Elegir destinatario solo entre companeros con ubicaciones plausibles.
function elegirPase() {
    const origen = posiciones[s.dueno];
    if (!origen) return null;
    let candidatos = [];
    for (const id of IDS) {
        if (id===s.dueno || id==='p1') continue;
        const q=posiciones[id];
        const dist=Math.hypot(q.x-origen.x,q.y-origen.y);
        const avance=q.x-origen.x;
        if (dist<7 || dist>42 || avance < -22) continue;
        let peso=1;
        if (avance>3) peso+=2;
        if (avance>12) peso+=1.5;
        if (id==='p8') peso+=1;
        if ((id==='p10' && origen.y<34)||(id==='p11' && origen.y>=34)) peso+=1.5;
        if (id==='p9' && origen.x>62) peso+=1.8;
        if (avance < -4) peso *= 0.65;
        candidatos.push({id, peso, dist});
    }
    if (!candidatos.length) {
        candidatos=IDS.filter(id=>id!==s.dueno && id!=='p1').map(id=>({
            id, peso:1/(1+Math.hypot(posiciones[id].x-origen.x,posiciones[id].y-origen.y))
        }));
    }
    const suma=candidatos.reduce((a,b)=>a+b.peso,0);
    let r=Math.random()*suma;
    for (const c of candidatos) {r-=c.peso;if (r<=0) return c.id;}
    return candidatos[candidatos.length-1].id;
}

//Un balon, un poseedor y pases interpolados (sin saltos aleatorios).
if (s.posesion==='propia') {
    if (s.pase) {
        //El receptor puede seguir corriendo mientras recibe el pase.
        const destinoMovil=posiciones[s.pase.receptor];
        if (destinoMovil) {
            s.pase.hastaX=destinoMovil.x;
            s.pase.hastaY=destinoMovil.y;
        }
        s.pase.avance++;
        const t=clamp(s.pase.avance/s.pase.duracion,0,1);
        s.balon.x=s.pase.desdeX+(s.pase.hastaX-s.pase.desdeX)*t;
        s.balon.y=s.pase.desdeY+(s.pase.hastaY-s.pase.desdeY)*t;
        if (t>=1) {
            s.dueno=s.pase.receptor;
            s.balon={x:posiciones[s.dueno].x,y:posiciones[s.dueno].y};
            s.pase=null;s.desdePase=0;
        }
    } else if (s.dueno && posiciones[s.dueno]) {
        s.balon={x:posiciones[s.dueno].x,y:posiciones[s.dueno].y};
        s.desdePase++;
        //Pases moderados cada 5-8 segundos (en transicion, mas rapidos).
        const intervalo=s.fase==='transicion_ofensiva'?4:6;
        if (s.desdePase>=intervalo && s.restante>3) {
            const receptor=elegirPase();
            if (receptor) {
                const r=posiciones[receptor];
                const d=Math.hypot(r.x-s.balon.x,r.y-s.balon.y);
                s.pase={receptor,desdeX:s.balon.x,desdeY:s.balon.y,
                    hastaX:r.x,hastaY:r.y,avance:0,duracion:Math.max(1,Math.ceil(d/16))};
                s.evento='Pase de '+s.dueno.toUpperCase()+' a '+receptor.toUpperCase();
                s.ultimoEvento=s.t;
                s.desdePase=0;
            }
        }
    }
} else {
    //Rival virtual: avance hacia nuestra porteria y cambios suaves de carril.
    const deltaX = s.fase==='presion_alta' ? 1.3 : 1.7;
    s.balon.x=clamp(s.balon.x-deltaX,17,99);
    const yMeta=34+Math.sin(s.t/11)*20;
    s.balon.y=clamp(s.balon.y+(yMeta-s.balon.y)*0.10,3,65);
}
s.balon.x=clamp(s.balon.x,0,LARGO);
s.balon.y=clamp(s.balon.y,0,ANCHO);

//Posiciones colectivas: todas dependen de la misma posicion del balon.
const b=s.balon;
const ataque=s.posesion==='propia';
const defensores=['p2','p3','p4','p5'];
const centro=['p6','p7','p8'];
const bandas=['p10','p11'];
const shiftY=(b.y-34);
const posicionesObjetivo={};
const fija=(id,x,y)=>{posicionesObjetivo[id]={x:clamp(x,1,104),y:clamp(y,2,66)};};
if (ataque) {
    const extra=s.fase==='transicion_ofensiva'?2:0;
    fija('p1', clamp(5+(b.x-45)*.018,4,8),clamp(34+shiftY*.12,29,39));
    const linea=clamp(b.x-32,22,63);
    fija('p4', linea, 26+shiftY*.18);
    fija('p5', linea, 42+shiftY*.18);
    fija('p2', clamp(b.x-(b.y<30?8:19)+extra,30,89), 9+shiftY*.15);
    fija('p3', clamp(b.x-(b.y>38?8:19)+extra,30,89), 59+shiftY*.15);
    fija('p6', clamp(b.x-15+extra,39,82), 20+shiftY*.25);
    fija('p7', clamp(b.x-15+extra,39,82), 48+shiftY*.25);
    fija('p8', clamp(b.x+5+extra,58,91), 34+shiftY*.35);
    fija('p9', clamp(b.x+18+extra,76,100), 34+shiftY*.22);
    fija('p10',clamp(b.x+11+extra,68,101), 10+shiftY*.14);
    fija('p11',clamp(b.x+11+extra,68,101), 58+shiftY*.14);
} else {
    const linea=clamp(b.x-25,14,43);
    fija('p1',clamp(4+(b.x-20)*.027,4,7),clamp(34+shiftY*.13,28,40));
    fija('p2',linea,10+shiftY*.22);
    fija('p3',linea,58+shiftY*.22);
    fija('p4',linea-3,27+shiftY*.38);
    fija('p5',linea-3,41+shiftY*.38);
    fija('p6',linea+15,21+shiftY*.35);
    fija('p7',linea+15,47+shiftY*.35);
    fija('p8',linea+26,34+shiftY*.44);
    fija('p9',linea+42,34+shiftY*.26);
    fija('p10',linea+32,11+shiftY*.23);
    fija('p11',linea+32,57+shiftY*.23);
}

//Persiguen el balon SOLO 2 o 3 jugadores cercanos.
//El resto conserva coberturas y distancias entre lineas.
const perseguidores=[];
if (!ataque) {
    let disponibles=IDS.filter(id=>id!=='p1').map(id=>({
        id, distancia:Math.hypot(posiciones[id].x-b.x,posiciones[id].y-b.y)
    })).sort((a,c)=>a.distancia-c.distancia);
    const cupo=s.fase==='presion_alta'?3:2;
    for (const c of disponibles) {
        if (perseguidores.length>=cupo) break;
        if (c.distancia < (s.fase==='presion_alta'?30:18)) perseguidores.push(c.id);
    }
    perseguidores.forEach((id,i)=>{
        const offset=[[-1.5,0],[2.4,-2.5],[2.4,2.5]][i];
        fija(id,b.x+offset[0],b.y+offset[1]);
    });
}

//El poseedor conduce el balon. Los demas dan opciones y mantienen estructura.
if (ataque && s.dueno && !s.pase) {
    const p=posiciones[s.dueno];
    const ataca=s.dueno==='p9'||s.dueno==='p10'||s.dueno==='p11';
    fija(s.dueno,
        clamp(p.x+(ataca?3.5:5.5),9,ataca?98:94),
        clamp(p.y+(34-p.y)*.08,4,64));
}
//Dos jugadores nunca reciben la misma posicion objetivo exacta.
for (let i=0;i<IDS.length;i++) {
    for (let j=i+1;j<IDS.length;j++) {
        const a=posicionesObjetivo[IDS[i]],c=posicionesObjetivo[IDS[j]];
        const d=Math.hypot(a.x-c.x,a.y-c.y);
        if(d<4 && d>0) {
            const dir=(c.y>=a.y?1:-1);
            c.y=clamp(c.y+dir*(4-d),2,66);
        }
    }
}

const ordenes=IDS.map(id=>{
    const p=posiciones[id],dest=posicionesObjetivo[id];
    const d=Math.hypot(dest.x-p.x,dest.y-p.y);
    const esPortero=id==='p1';
    const max=esPortero?12:defensores.includes(id)?25:centro.includes(id)?29:32;
    const presion=perseguidores.includes(id);
    let velocidad=d<.5?0:clamp(4.5+d*1.35,5,max);
    if(presion)velocidad=clamp(Math.max(velocidad,15),0,max);
    if(s.dueno===id && ataque && !s.pase)velocidad=clamp(11+d*.45,9,18);
    let modo=presion?'presionar':ataque?'apoyo_colectivo':'bloque_defensivo';
    if(s.dueno===id && ataque && !s.pase) modo='conduccion';
    if(s.fase==='transicion_defensiva' && !presion)modo='repliegue';
    if(s.fase==='transicion_ofensiva')modo='contraataque';
    if(s.fase==='presion_alta' && presion)modo='presion_alta';
    if(esPortero)modo='colocacion_portero';
    return {player:id,topic:'ordenes/'+id,payload:{
        modo, objetivoX:rnd(dest.x),objetivoY:rnd(dest.y),
        velocidadObjetivo:rnd(velocidad),reset:reinicio,
        tick:s.t, fase:s.fase
    }};
});

s.t++;
s.restante--;
context.set('partido',s);
flow.set('posicionesTacticas',posiciones);
node.status({fill:s.posesion==='propia'?'green':'blue',shape:'dot',
    text:FASES[s.fase]+' · '+s.restante+' s · balon '+rnd(b.x)+','+rnd(b.y)});

const resumen={
    topic:'equipo/estado',payload:{
        timestamp:new Date().toISOString(),
        segundo:s.t,
        fase:s.fase,descripcionFase:FASES[s.fase],
        posesion:s.posesion,
        formacion:'4-2-3-1',
        balon:{X:rnd(b.x),Y:rnd(b.y),poseedor:s.pase?null:s.dueno,
            paseHacia:s.pase?s.pase.receptor:null, estado:s.pase?'en_pase':(s.posesion==='rival'?'rival':'conduccion')},
        evento:s.evento,
        jugadoresPresionando:perseguidores,
        segundosRestantesFase:s.restante,
        //Posiciones objetivo utiles para depurar, no sustituyen al GPS real.
        objetivos:Object.fromEntries(IDS.map(id=>[id,{X:rnd(posicionesObjetivo[id].x),Y:rnd(posicionesObjetivo[id].y)}]))
    }
};
return [ordenes, resumen];

const DT = 1;
const LARGO_CAMPO = 105;
const ANCHO_CAMPO = 68;
const PORTERIA_X = 0;

const ACELERACION_MAX = 2.0;  //m/s2
const FRENADA_MAX = 3.0;      //m/s2
const GIRO_MAX = 90;          //grados por segundo
const PULSO_BASE = 90;        //bpm, valor inicial orientativo
const TEMPERATURA_BASE = 36.7; //temperatura corporal inicial, grados C
const LONGITUD_PASO = 0.75;   //metros por apoyo, aproximacion

const aleatorio = (min, max) => min + Math.random() * (max - min);
const limitar = (v, min, max) => Math.max(min, Math.min(max, v));
const normalizarAngulo = a => ((a + 540) % 360) - 180;

//Orden tactica compartida: sustituye a las decisiones aleatorias aisladas.
//El calculo de los cinco sensores que sigue conserva la plantilla maestra.
const orden = msg.payload || {};
if (orden.reset === true) {
    context.set("estado", null);
}
let s = context.get("estado") || { //Marcador para estado inicial
    x: 4, y: 34,
    vx: 0, vy: 0, distancia: 0,
    modo: "parado", segundos: 0,
    objetivoX: 4, objetivoY: 34,
    velocidadObjetivo: 0, angulo: 0,
    carga: 0, pulso: PULSO_BASE, temperatura: TEMPERATURA_BASE, fasePaso: 0
};
if (!Number.isFinite(s.angulo)) s.angulo = 0;
if (!Number.isFinite(s.carga)) s.carga = 0;
if (!Number.isFinite(s.pulso)) s.pulso = PULSO_BASE;
if (!Number.isFinite(s.temperatura)) s.temperatura = TEMPERATURA_BASE;
if (!Number.isFinite(s.fasePaso)) s.fasePaso = 0;

if (Number.isFinite(orden.objetivoX) && Number.isFinite(orden.objetivoY)) {
    s.modo = String(orden.modo || "apoyo_colectivo");
    s.objetivoX = limitar(orden.objetivoX, 0, LARGO_CAMPO);
    s.objetivoY = limitar(orden.objetivoY, 0, ANCHO_CAMPO);
    s.velocidadObjetivo = limitar(Number(orden.velocidadObjetivo) || 0, 0, 36);
    s.segundos = 1;
} else {
    //Si el mensaje no contiene orden tactica valida, no se mueve.
    s.modo = "parado";
    s.objetivoX = s.x;
    s.objetivoY = s.y;
    s.velocidadObjetivo = 0;
    s.segundos = 1;
}

//GPS: calcular desplazamiento y velocidad.
const dx = s.objetivoX - s.x;
const dy = s.objetivoY - s.y;
const distanciaObjetivo = Math.hypot(dx, dy);
const velocidadAnterior = Math.hypot(s.vx, s.vy);
const velocidadDeseada = Math.min(
    s.velocidadObjetivo / 3.6,
    Math.sqrt(2 * FRENADA_MAX * distanciaObjetivo)
);

const vxDeseada = distanciaObjetivo > 0.001
    ? dx / distanciaObjetivo * velocidadDeseada : 0;

const vyDeseada = distanciaObjetivo > 0.001
    ? dy / distanciaObjetivo * velocidadDeseada : 0;

const dvx = vxDeseada - s.vx;
const dvy = vyDeseada - s.vy;

const cambioVector = Math.hypot(dvx, dvy);

const limite = velocidadDeseada < velocidadAnterior
    ? FRENADA_MAX : ACELERACION_MAX;

const factor = cambioVector > 0
    ? Math.min(1, limite * DT / cambioVector) : 0;

s.vx += dvx * factor;
s.vy += dvy * factor;

const xAnterior = s.x;
const yAnterior = s.y;

s.x = limitar(s.x + s.vx * DT, 0, LARGO_CAMPO);
s.y = limitar(s.y + s.vy * DT, 0, ANCHO_CAMPO);

s.vx = (s.x - xAnterior) / DT;
s.vy = (s.y - yAnterior) / DT;

const velocidadActual = Math.hypot(s.vx, s.vy);

const desplazamiento = Math.hypot(s.x - xAnterior, s.y - yAnterior);

s.distancia += desplazamiento;

//Acelerometro: cambios de rapidez entre lecturas.
const deltaRapidez = (velocidadActual - velocidadAnterior) / DT;
const aceleracion = Math.max(0, deltaRapidez);
const desaceleracion = Math.max(0, -deltaRapidez);

//Giroscopio: variacion de orientacion por segundo.
let anguloObjetivo = s.angulo;

if (velocidadActual > 0.25) {
    anguloObjetivo = Math.atan2(s.vy, s.vx) * 180 / Math.PI;
} else if (s.modo !== "parado" && distanciaObjetivo > 0.3) {
    anguloObjetivo = Math.atan2(dy, dx) * 180 / Math.PI;
}

const giro = limitar(
    normalizarAngulo(anguloObjetivo - s.angulo),
    -GIRO_MAX * DT, GIRO_MAX * DT);

s.angulo = normalizarAngulo(s.angulo + giro);

//Pulsometro: esfuerzo acumulado, respuesta lenta y recuperacion.
//La intensidad depende de velocidad y de aceleraciones positivas.
const intensidad = limitar(
    0.8 * limitar(velocidadActual / 6.1, 0, 1) +
    0.2 * limitar(aceleracion / ACELERACION_MAX, 0, 1),
    0, 1
);

//La carga aumenta mas deprisa de lo que se disipa.
const alphaCarga = intensidad > s.carga ? 0.18 : 0.04;
s.carga += (intensidad - s.carga) * alphaCarga;

//Al aumentar la carga, sube el pulso objetivo (hasta ~170 bpm).
const pulsoObjetivo = PULSO_BASE + 80 * s.carga;
const alphaPulso = pulsoObjetivo > s.pulso ? 0.13 : 0.035;
const ruido = aleatorio(-0.25, 0.25);
s.pulso = limitar(
    s.pulso + (pulsoObjetivo - s.pulso) * alphaPulso + ruido,
    60, 180
);

//Termometro: temperatura corporal simulada, asociada a la carga de esfuerzo.
//Respuesta lenta: sube durante la actividad y desciende aun mas despacio al recuperar.
//No es una medicion fisiologica validada ni reproduce un termometro clinico.
const temperaturaObjetivo = TEMPERATURA_BASE + 1.25 * s.carga;
const alphaTemperatura = temperaturaObjetivo > s.temperatura ? 0.004 : 0.0018;
const ruidoTemperatura = aleatorio(-0.001, 0.001);
s.temperatura = limitar(
    s.temperatura + (temperaturaObjetivo - s.temperatura) * alphaTemperatura + ruidoTemperatura,
    36.2, 39.0
);

//Sensor de presion: reparto porcentual de carga entre ambos pies.
//50/50 aproximadamente en reposo. Durante el desplazamiento,
//la carga alterna con las pisadas y se desplaza lateralmente.
//Es una distribucion relativa, NO presion absoluta en kPa.
const actividad = limitar(velocidadActual / 6.1, 0, 1);

//Cada 0.75 m de avance alterna el pie de apoyo.
s.fasePaso = (s.fasePaso + Math.PI * desplazamiento / LONGITUD_PASO)
    % (2 * Math.PI);
const repartoPorPisada = Math.sin(s.fasePaso) * 30 * Math.sqrt(actividad);

//Asumimos X hacia la derecha e Y hacia arriba en el campo.
const velocidadDerecha = PORTERIA_X === 0 ? -s.vy : s.vy;
const sesgoLateral = 10 * limitar(velocidadDerecha / 3, -1, 1);

//Ligera variacion de apoyo (incluido en reposo).
const ruidoApoyo = aleatorio(-1.5, 1.5);
const presionDerecha = Number(limitar(
    50 + repartoPorPisada + sesgoLateral + ruidoApoyo,
    5, 95
).toFixed(1));
const presionIzquierda = Number((100 - presionDerecha).toFixed(1));

//Guardar el estado actualizado.
s.segundos--;
if (s.modo !== "parado" &&
    Math.hypot(s.objetivoX - s.x, s.objetivoY - s.y) < 0.5 &&
    velocidadActual < 0.5) {
    s.segundos = 0;
}
context.set("estado", s);
