const alphaTemperatura = temperaturaObjetivo > s.temperatura ? 0.004 : 0.0018;
const ruidoTemperatura = aleatorio(-0.001, 0.001);
s.temperatura = limitar(
    s.temperatura + (temperaturaObjetivo - s.temperatura) * alphaTemperatura + ruidoTemperatura,
    36.2, 39.0
);

