let s = context.get("estado") || { //Marcador para estado inicial
    x: 77, y: 58,
    vx: 0, vy: 0, distancia: 0,
    modo: "parado", segundos: 0,
    objetivoX: 77, objetivoY: 58,
    velocidadObjetivo: 0, angulo: 0,
    carga: 0, pulso: PULSO_BASE, temperatura: TEMPERATURA_BASE, fasePaso: 0
};
if (!Number.isFinite(s.angulo)) s.angulo = 0;
if (!Number.isFinite(s.carga)) s.carga = 0;
if (!Number.isFinite(s.pulso)) s.pulso = PULSO_BASE;
if (!Number.isFinite(s.temperatura)) s.temperatura = TEMPERATURA_BASE;
if (!Number.isFinite(s.fasePaso)) s.fasePaso = 0;

if (Number.isFinite(orden.objetivoX) && Number.isFinite(orden.objetivoY)) {
    s.modo = String(orden.modo || "apoyo_colectivo");
    s.objetivoX = limitar(orden.objetivoX, 0, LARGO_CAMPO);
    s.objetivoY = limitar(orden.objetivoY, 0, ANCHO_CAMPO);
    s.velocidadObjetivo = limitar(Number(orden.velocidadObjetivo) || 0, 0, 36);
    s.segundos = 1;
} else {
    //Si el mensaje no contiene orden tactica valida, no se mueve.
    s.modo = "parado";
    s.objetivoX = s.x;
    s.objetivoY = s.y;
    s.velocidadObjetivo = 0;
    s.segundos = 1;
}

//GPS: calcular desplazamiento y velocidad.
const dx = s.objetivoX - s.x;
const dy = s.objetivoY - s.y;
const distanciaObjetivo = Math.hypot(dx, dy);
const velocidadAnterior = Math.hypot(s.vx, s.vy);
const velocidadDeseada = Math.min(
    s.velocidadObjetivo / 3.6,
    Math.sqrt(2 * FRENADA_MAX * distanciaObjetivo)
);

const vxDeseada = distanciaObjetivo > 0.001
    ? dx / distanciaObjetivo * velocidadDeseada : 0;

const vyDeseada = distanciaObjetivo > 0.001
    ? dy / distanciaObjetivo * velocidadDeseada : 0;

const dvx = vxDeseada - s.vx;
const dvy = vyDeseada - s.vy;

const cambioVector = Math.hypot(dvx, dvy);

const limite = velocidadDeseada < velocidadAnterior
    ? FRENADA_MAX : ACELERACION_MAX;

const factor = cambioVector > 0
    ? Math.min(1, limite * DT / cambioVector) : 0;

s.vx += dvx * factor;
s.vy += dvy * factor;

const xAnterior = s.x;
const yAnterior = s.y;

s.x = limitar(s.x + s.vx * DT, 0, LARGO_CAMPO);
s.y = limitar(s.y + s.vy * DT, 0, ANCHO_CAMPO);

s.vx = (s.x - xAnterior) / DT;
s.vy = (s.y - yAnterior) / DT;

const velocidadActual = Math.hypot(s.vx, s.vy);

const desplazamiento = Math.hypot(s.x - xAnterior, s.y - yAnterior);

s.distancia += desplazamiento;

//Acelerometro: cambios de rapidez entre lecturas.
const deltaRapidez = (velocidadActual - velocidadAnterior) / DT;
const aceleracion = Math.max(0, deltaRapidez);
const desaceleracion = Math.max(0, -deltaRapidez);

//Giroscopio: variacion de orientacion por segundo.
let anguloObjetivo = s.angulo;

if (velocidadActual > 0.25) {
    anguloObjetivo = Math.atan2(s.vy, s.vx) * 180 / Math.PI;
} else if (s.modo !== "parado" && distanciaObjetivo > 0.3) {
    anguloObjetivo = Math.atan2(dy, dx) * 180 / Math.PI;
}

const giro = limitar(
    normalizarAngulo(anguloObjetivo - s.angulo),
    -GIRO_MAX * DT, GIRO_MAX * DT);

s.angulo = normalizarAngulo(s.angulo + giro);

//Pulsometro: esfuerzo acumulado, respuesta lenta y recuperacion.
//La intensidad depende de velocidad y de aceleraciones positivas.
const intensidad = limitar(
    0.8 * limitar(velocidadActual / 6.1, 0, 1) +
    0.2 * limitar(aceleracion / ACELERACION_MAX, 0, 1),
    0, 1
);

//La carga aumenta mas deprisa de lo que se disipa.
const alphaCarga = intensidad > s.carga ? 0.18 : 0.04;
s.carga += (intensidad - s.carga) * alphaCarga;

//Al aumentar la carga, sube el pulso objetivo (hasta ~170 bpm).
const pulsoObjetivo = PULSO_BASE + 80 * s.carga;
const alphaPulso = pulsoObjetivo > s.pulso ? 0.13 : 0.035;
const ruido = aleatorio(-0.25, 0.25);
s.pulso = limitar(
    s.pulso + (pulsoObjetivo - s.pulso) * alphaPulso + ruido,
    60, 180
);

//Termometro: temperatura corporal simulada, asociada a la carga de esfuerzo.
//Respuesta lenta: sube durante la actividad y desciende aun mas despacio al recuperar.
//No es una medicion fisiologica validada ni reproduce un termometro clinico.
const temperaturaObjetivo = TEMPERATURA_BASE + 1.25 * s.carga;
const alphaTemperatura = temperaturaObjetivo > s.temperatura ? 0.004 : 0.0018;
const ruidoTemperatura = aleatorio(-0.001, 0.001);
s.temperatura = limitar(
    s.temperatura + (temperaturaObjetivo - s.temperatura) * alphaTemperatura + ruidoTemperatura,
    36.2, 39.0
);

//Sensor de presion: reparto porcentual de carga entre ambos pies.
//50/50 aproximadamente en reposo. Durante el desplazamiento,
//la carga alterna con las pisadas y se desplaza lateralmente.
//Es una distribucion relativa, NO presion absoluta en kPa.
const actividad = limitar(velocidadActual / 6.1, 0, 1);

//Cada 0.75 m de avance alterna el pie de apoyo.
s.fasePaso = (s.fasePaso + Math.PI * desplazamiento / LONGITUD_PASO)
    % (2 * Math.PI);
const repartoPorPisada = Math.sin(s.fasePaso) * 30 * Math.sqrt(actividad);

//Asumimos X hacia la derecha e Y hacia arriba en el campo.
const velocidadDerecha = PORTERIA_X === 0 ? -s.vy : s.vy;
const sesgoLateral = 10 * limitar(velocidadDerecha / 3, -1, 1);

//Ligera variacion de apoyo (incluido en reposo).
const ruidoApoyo = aleatorio(-1.5, 1.5);
const presionDerecha = Number(limitar(
    50 + repartoPorPisada + sesgoLateral + ruidoApoyo,
    5, 95
).toFixed(1));
const presionIzquierda = Number((100 - presionDerecha).toFixed(1));

//Guardar el estado actualizado.
s.segundos--;
if (s.modo !== "parado" &&
    Math.hypot(s.objetivoX - s.x, s.objetivoY - s.y) < 0.5 &&
    velocidadActual < 0.5) {
    s.segundos = 0;
}
context.set("estado", s);
//Compartir ubicacion GPS real con el motor central para cerrar el bucle tactico.
const posicionesEquipo = flow.get("posicionesTacticas") || {};
posicionesEquipo["p11"] = {x:s.x, y:s.y, vx:s.vx, vy:s.vy, tick:orden.tick};
flow.set("posicionesTacticas", posicionesEquipo);

const posicionX = PORTERIA_X === 0 ? s.x : LARGO_CAMPO - s.x;
const giroGlobal = PORTERIA_X === 0 ? giro : -giro;

//Seis publicaciones MQTT
const mensajeGPS = {
    topic: "p11/sensors/gps",
    payload: {
        speed: { unit: "km/h", value: Number((velocidadActual * 3.6).toFixed(2)) },
        distancecovered: { unit: "m", value: Number(s.distancia.toFixed(2)) },
        position: {
            X: { unit: "m", value: Number(posicionX.toFixed(2)) },
            Y: { unit: "m", value: Number(s.y.toFixed(2)) }
        }
    }
};

const mensajeAcelerometro = {
    topic: "p11/sensors/accelerometer",
    payload: {
        acceleration: { unit: "m/s2", value: Number(aceleracion.toFixed(2)) },
        desacceleration: { unit: "m/s2", value: Number(desaceleracion.toFixed(2)) }
    }
};

const mensajeGiroscopio = {
    topic: "p11/sensors/giroscope",
    payload: {
        changeinposition: { unit: "degrees", value: Number(giroGlobal.toFixed(2)) }
    }
};

const mensajePulsometro = {
    topic: "p11/sensors/pulsemeter",
    payload: {
        pulse: { unit: "bpm", value: Math.round(s.pulso) }
    }
};

const mensajePresion = {
    topic: "p11/sensors/pressuresensor",
    payload: {
        pressureleftfoot: { unit: "%", value: presionIzquierda },
        pressurerightfoot: { unit: "%", value: presionDerecha }
    }
};

const mensajeTermometro = {
    topic: "p11/sensors/thermometer",
    payload: {
        temperature: { unit: "C", value: Number(s.temperatura.toFixed(2)) }
    }
};

return [[
    mensajeGPS,
    mensajeAcelerometro,
    mensajeGiroscopio,
    mensajePulsometro,
    mensajePresion,
    mensajeTermometro
]];

// Mismos rangos que la API (api/services/simulador.js): si no, el simulador descarta órdenes que la API ya dio por buenas
const DURACION_PREDETERMINADA = 30;
const DURACION_MAXIMA = 86400; // 24 horas

//1. Identificar al jugador mediante el topic
const coincidencia = String(msg.topic || "").match(
    /^control\/jugadores\/(p(?:[1-9]|10|11))\/sensores$/
);

if (!coincidencia) {
    node.warn("Topic de control no válido");
    return null;
}

const jugador = coincidencia[1];

//2. Interpretar el payload JSON
let datos = msg.payload;

if (typeof datos === "string" ||
    (typeof Buffer !== "undefined" && Buffer.isBuffer(datos))) {
    try {
        datos = JSON.parse(String(datos));
    } catch (error) {
        node.warn("JSON de control no válido");
        return null;
    }
}

if (!datos || typeof datos !== "object" ||
    Array.isArray(datos)) {
    node.warn("El payload debe ser un objeto JSON");
    return null;
}

//3. Recuperar los ajustes anteriores
const ajustes = flow.get("ajustesSensores") || {};

//4. Eliminar los ajustes de un jugador
if (datos.reset === true) {
    delete ajustes[jugador];
    flow.set("ajustesSensores", ajustes);

    node.status({
        fill: "grey",
        shape: "dot",
        text: jugador.toUpperCase() + " | simulación normal"
    });

    return null;
}

//5. Validar valores de sensores
if (datos.pulse === undefined &&
    datos.temperature === undefined) {
    node.warn("Debes indicar pulso o temperatura");
    return null;
}

if (datos.pulse !== undefined &&
    (!Number.isFinite(datos.pulse) ||
     datos.pulse < 30 || datos.pulse > 220)) {
    node.warn("Pulso fuera del rango 30-220 bpm");
    return null;
}

if (datos.temperature !== undefined &&
    (!Number.isFinite(datos.temperature) ||
     datos.temperature < 35 ||
     datos.temperature > 42)) {
    node.warn("Temperatura fuera del rango 35-42 C");
    return null;
}

// 6. Determinar la modalidad de duración
// durationSeconds: 0 es "hasta que se quite", como en la API
const modo = datos.mode || (datos.durationSeconds === 0 ? "indefinite" : "duration");

if (!["duration", "once", "indefinite"].includes(modo)) {
    node.warn("Modo de duración no válido");
    return null;
}

let expira = null;
let unaLectura = false;
let descripcionDuracion = "";

if (modo === "once") {
    unaLectura = true;
    descripcionDuracion = "una lectura";

} else if (modo === "indefinite") {
    expira = null;
    descripcionDuracion = "indefinido";

} else {
    const duracion = datos.durationSeconds === undefined
        ? DURACION_PREDETERMINADA
        : datos.durationSeconds;

    if (!Number.isInteger(duracion) ||
        duracion < 1 ||
        duracion > DURACION_MAXIMA) {
        node.warn("durationSeconds debe estar entre 1 y 86400");
        return null;
    }

    expira = Date.now() + duracion * 1000;
    descripcionDuracion = duracion + " segundos";
}

//7. Conservar otros ajustes vigentes del jugador
const ajusteJugador = ajustes[jugador] || {};

//Cada sensor mantiene su propia duración
if (datos.pulse !== undefined) {
    ajusteJugador.pulse = {
        value: datos.pulse,
        expiresAt: expira,
        once: unaLectura
    };
}

if (datos.temperature !== undefined) {
    ajusteJugador.temperature = {
        value: datos.temperature,
        expiresAt: expira,
        once: unaLectura
    };
}

//8. Guardar en el contexto compartido
ajustes[jugador] = ajusteJugador;

flow.set("ajustesSensores", ajustes);

//9. Mostrar información del último ajuste
node.status({
    fill: "green",
    shape: "dot",
    text: jugador.toUpperCase() + " | " + descripcionDuracion
});

//No emitir mensajes: el ajuste queda almacenado
return null;

//1. Identificar jugador y sensor
const partes = String(msg.topic || "").split("/");

if (partes.length !== 3 ||
    partes[1] !== "sensors") {
    return msg;
}

const jugador = partes[0];
const sensor = partes[2];

if (!/^p(?:[1-9]|10|11)$/.test(jugador)) {
    return msg;
}

//2. Consultar los ajustes compartidos
const ajustes = flow.get("ajustesSensores") || {};
const ajusteJugador = ajustes[jugador];

if (!ajusteJugador) {
    return msg;
}

//3. Identificar el ajuste correspondiente
let campo = null;
let propiedad = null;

if (sensor === "pulsemeter") {
    campo = "pulse";
    propiedad = "pulse";

} else if (sensor === "thermometer") {
    campo = "temperature";
    propiedad = "temperature";

} else {
    //Los demás sensores pasan sin modificación
    return msg;
}

const ajuste = ajusteJugador[campo];

if (!ajuste || !Number.isFinite(ajuste.value)) {
    return msg;
}

//4. Comprobar caducidad
const ahora = Date.now();

if (ajuste.expiresAt !== null &&
    Number.isFinite(ajuste.expiresAt) &&
    ahora >= ajuste.expiresAt) {

    delete ajusteJugador[campo];

    if (Object.keys(ajusteJugador).length === 0) {
        delete ajustes[jugador];
    }

    flow.set("ajustesSensores", ajustes);

    //El dato vuelve a su valor simulado
    return msg;
}

//5. Aplicar el valor forzado
if (!msg.payload ||
    !msg.payload[propiedad] ||
    typeof msg.payload[propiedad] !== "object") {
    return msg;
}

if (sensor === "pulsemeter") {
    msg.payload.pulse.value = Math.round(ajuste.value);
}

if (sensor === "thermometer") {
    msg.payload.temperature.value =
        Number(ajuste.value.toFixed(2));
}

//6. Si era para una sola lectura, eliminarlo
if (ajuste.once === true) {
    delete ajusteJugador[campo];

    if (Object.keys(ajusteJugador).length === 0) {
        delete ajustes[jugador];
    }

    flow.set("ajustesSensores", ajustes);
}

//7. Enviar el mensaje al nodo JSON
return msg;
